function resetMerchantTransactions(){if(transactionMerchant===M?.id)return;transactionMerchant=M?.id;currentTransactionSettings=null;merchantMappingTemplates=[];wizard={step:1,files:[],batch:null,mappings:{},validation:null,previewOffset:0,previewSize:10,worksheets:{},inspection:null,inspecting:false};historyOffset=0;historyRequest++;runPage=0;qualitySnapshot=null;qualityRequest++;qualitySelectedRun=null;qualityDetailRequest++;qualityAlertPage=0;$('#quality-attention').replaceChildren();$('#alert-pagination').replaceChildren();if($('#run-dialog').open)$('#run-dialog').close();$('#tledger').replaceChildren();$('#history-pagination').replaceChildren();for(const id of ['quality-kpis','quality-runs','quality-alerts','run-pagination'])$('#'+id).replaceChildren();singleKey=crypto.randomUUID();$('#pos-files').value='';$('#pos-folder').value='';$('#mapping-forms').replaceChildren();showWizardStep(1);renderFiles();}
function renderWizardProgress(){const worksheetPhase=wizard.files.some(f=>/\.xlsx$/i.test(f.name)),current=wizard.step===1?(worksheetPhase&&wizard.inspection?1:0):wizard.step;[...$('#wizard-progress').children].forEach((li,i)=>{li.hidden=i===1&&!worksheetPhase;li.classList.toggle('current',i===current);li.classList.toggle('complete',i<current);if(i===current)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')});
 // Overall bar: completed visible steps out of all visible steps (the Import step counts as done once it is reached).
 const visible=[...$('#wizard-progress').children].map((li,i)=>[li,i]).filter(([li])=>!li.hidden),position=Math.max(0,visible.findIndex(([,i])=>i===current)),last=visible.length-1,percent=Math.round((position===last?1:position/last)*100);
 if($('#import-progress-fill')){$('#import-progress-fill').style.width=percent+'%';$('#import-progress-bar').setAttribute('aria-valuenow',String(percent));$('#import-progress-label').textContent='Step '+(position+1)+' of '+visible.length+' · '+(visible[position]?.[0].textContent||'')}}
function showWizardStep(step){wizard.step=step;for(let i=1;i<=5;i++)$('#wizard-step-'+i).hidden=i!==step;renderWizardProgress()}
async function loadTransactions(){resetMerchantTransactions();$('#single-save').disabled=true;const mid=M.id,s=await fetchTransactionSettings();if(M?.id!==mid)return;$('#tcurrency').innerHTML='<option value="'+esc(s.base_currency)+'">'+esc(currencyLabel(s.base_currency))+'</option>';$('#tcurrency').disabled=true;$('#transaction-zone').textContent='Business local time: '+s.timezone+' · Display '+s.display_date_format;const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:s.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()),get=k=>parts.find(p=>p.type===k).value;$('#tdate').value=get('year')+'-'+get('month')+'-'+get('day')+'T'+get('hour')+':'+get('minute');$('#tstatus').value=s.default_status;$('#singleform').querySelectorAll('input,select,button').forEach(e=>e.disabled=e.id==='tcurrency'||!mtCan('create_transactions'));await loadLedger();}
async function loadPOSImport(){resetMerchantTransactions();await loadImportSettings();showWizardStep(wizard.step);renderFiles();}
// Import requests report progress: upload bytes as a percentage, then an indeterminate bar while the server works.
const POS_ACTIVITY={'/inspect':'Reading worksheets','/stage':'Uploading and staging files','/validate':'Validating and reconciling rows','/commit':'Importing transactions'};
function importActivity(label,percent){
 const box=$('#import-activity');if(!box)return;if(label===null){box.hidden=true;return}
 box.hidden=false;$('#import-activity-label').textContent=label;const bar=$('#import-activity-bar');
 if(percent==null){box.classList.add('indeterminate');$('#import-activity-pct').textContent='';$('#import-activity-fill').style.width='';bar.removeAttribute('aria-valuenow')}
 else{box.classList.remove('indeterminate');const p=Math.max(0,Math.min(100,Math.round(percent)));$('#import-activity-pct').textContent=p+'%';$('#import-activity-fill').style.width=p+'%';bar.setAttribute('aria-valuenow',String(p))}
}
function posAPI(path,body){
 const name=Object.keys(POS_ACTIVITY).find(k=>path.endsWith(k)),label=name?POS_ACTIVITY[name]:'Working';
 return new Promise((resolve,reject)=>{
  const xhr=new XMLHttpRequest(),payload=JSON.stringify({merchant:M.id,...body}),large=payload.length>200000;
  xhr.open('POST','/api/pos-import'+path);xhr.setRequestHeader('Content-Type','application/json');xhr.setRequestHeader('X-CSRF-Token',SESSION?.csrf_token||'');
  importActivity(label+'…',large?0:null);
  if(large)xhr.upload.onprogress=e=>{if(e.lengthComputable)importActivity(label+'…',e.loaded/e.total*100)};
  xhr.upload.onload=()=>importActivity((name==='/stage'||name==='/inspect'?'Processing on the server':label)+'…',null);
  xhr.onload=()=>{let j={};try{j=JSON.parse(xhr.responseText||'{}')}catch{}
   if(xhr.status===401){location.href='/login';importActivity(null);return reject(Error('Sign in required'))}
   if(xhr.status>=400){importActivity(null);return reject(Error(j.error||'Request failed'))}
   importActivity(label+' · done',100);setTimeout(()=>importActivity(null),900);resolve({status:xhr.status,...(Array.isArray(j)?{list:j}:j)})};
  xhr.onerror=()=>{importActivity(null);reject(Error('The connection was interrupted. Please try again.'))};
  xhr.send(payload);
 });
}
$('#singleform').onsubmit=async e=>{e.preventDefault();const button=$('#single-save');$('#merchant').disabled=true;button.disabled=true;try{const entry={transaction_date:$('#tdate').value,net_amount:$('#tamount').value,currency:M.currency,transaction_type:$('#ttype').value,payment_method:$('#tchannel').value,status:$('#tstatus').value,external_reference:$('#tref').value,description:$('#tdesc').value,category:$('#tcategory').value};const r=await api('/api/merchant-transactions/entry',{method:'POST',body:JSON.stringify({merchant:M.id,entry,idempotency_key:singleKey})});if(!r.ok)throw Error(r.error||'Transaction was not committed');txnMessage('#tresult','Saved '+r.transaction_id+(r.reference?' · '+r.reference:''));singleKey=crypto.randomUUID();$('#tamount').value='';$('#tref').value='';$('#tdesc').value='';await loadLedger();await updateQualityBadge()}catch(e){txnMessage('#tresult',e.message,true)}finally{button.disabled=!mtCan('create_transactions');$('#merchant').disabled=false}};
const currencyLabel=c=>MerchantCurrency.label(c);
const titleLabel=v=>String(v).replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const importMoney=(v,c=M.currency)=>v==null?'Not provided':MerchantCurrency.format(v,c);
async function fileDescriptors(){const result=[];for(const [i,f] of wizard.files.entries()){const d={filename:f.name,relative_path:f.webkitRelativePath||f.name,content:base64(new Uint8Array(await f.arrayBuffer()))};if(/\.xlsx$/i.test(f.name))d.worksheets=(wizard.worksheets[i]||[]).filter(x=>x.selected).map(x=>x.detection?.status==='ready'?{name:x.name,detection_mode:'auto'}:{name:x.name,detection_mode:'reviewed',header_row:x.header_row,last_data_row:x.last_data_row,review_confirmed:x.review_confirmed===true});result.push(d)}return result}
function worksheetReady(sheet){return sheet.detection?.status==='ready'||(sheet.review_confirmed===true&&Number.isInteger(sheet.header_row)&&sheet.header_row>=1&&sheet.header_row<=10000&&Number.isInteger(sheet.last_data_row)&&sheet.last_data_row>sheet.header_row&&sheet.last_data_row<=20000)}
function filesReady(){const total=wizard.files.reduce((s,f)=>s+f.size,0);return mtCan('bulk_import')&&!wizard.inspecting&&wizard.files.length>0&&wizard.files.length<=10&&total<=10000000&&wizard.files.every((f,i)=>f.size>0&&f.size<=3000000&&(!/\.xlsx$/i.test(f.name)||((wizard.worksheets[i]||[]).some(x=>x.selected)&&(wizard.worksheets[i]||[]).filter(x=>x.selected).every(worksheetReady))))}
async function selectFiles(list){const files=[...list].filter(f=>/\.(csv|xlsx)$/i.test(f.name));wizard.files=files;wizard.batch=null;wizard.validation=null;wizard.worksheets={};wizard.inspection=null;wizard.inspecting=files.some(f=>/\.xlsx$/i.test(f.name));renderFiles();if(files.length!==list.length)txnMessage('#wizard-message','Unsupported files were excluded. CSV/XLSX only.',true);if(!wizard.inspecting)return;const identity=wizard.files,mid=M.id;try{const descriptors=[];for(const f of files)descriptors.push({filename:f.name,relative_path:f.webkitRelativePath||f.name,content:base64(new Uint8Array(await f.arrayBuffer()))});const r=await posAPI('/inspect',{files:descriptors});if(wizard.files!==identity||M.id!==mid)return;wizard.inspection=r;files.forEach((f,i)=>{wizard.worksheets[i]=(r.files[i].worksheets||[]).map(x=>({...x,selected:false,header_row:x.detection?.header_row||null,last_data_row:x.detection?.last_data_row||null,review_confirmed:false}))});txnMessage('#wizard-message','Select the worksheets to import. Transaction tables are detected automatically; uncertain data needs review. Formulas are not evaluated.')}catch(e){if(wizard.files===identity)txnMessage('#wizard-message',e.message,true)}finally{if(wizard.files===identity){wizard.inspecting=false;renderFiles()}}}
$('#pos-files').onchange=e=>selectFiles(e.target.files);$('#pos-folder').onchange=e=>selectFiles(e.target.files);
function detectedWorksheetHTML(sheet,i,j){const d=sheet.detection||{},review=d.status!=='ready',samples=d.review_rows?.length?d.review_rows:sheet.candidate_rows||[];return `<fieldset class="worksheet-source" data-book="${i}" data-sheet="${j}"><legend><label><input type="checkbox" data-sheet-selected ${sheet.selected?'checked':''}>${esc(sheet.name)}</label></legend><p class="worksheet-count">${d.transaction_count==null?'Transaction count needs review':countText(d.transaction_count)+' '+(review?'Candidate':'Detected')+' Transactions'}</p>${review?`<p class="banner note">Review needed. ${esc((d.reasons||['Transaction boundaries are uncertain.']).join(' '))}</p><details data-detected-review ${sheet.review_open?'open':''}><summary>Review Detected Data</summary><p class="muted">No uncertain rows have been silently discarded. Inspect the sample, then explicitly choose and confirm the transaction range. Formula cells within the selected range remain blocked.</p><div class="table-scroll"><table><thead><tr><th>Source Row</th><th>Values</th><th>Formula Cells</th></tr></thead><tbody>${samples.map(r=>'<tr><td>'+r.row+'</td><td>'+r.values.map(esc).join(' · ')+'</td><td>'+esc((r.formula_columns||[]).map(n=>String.fromCharCode(65+n)).join(', ')||'None')+'</td></tr>').join('')}</tbody></table></div><details data-advanced-range><summary>Advanced Row Range</summary><div class="grid g2"><label>Header Row<input type="number" data-header min="1" max="10000" value="${sheet.header_row||''}"></label><label>Last Data Row<input type="number" data-last min="2" max="20000" value="${sheet.last_data_row||''}"></label></div><p class="muted">Only the chosen range will be staged. Nonempty rows outside it will be excluded by your explicit selection. Count and monetary validation follow in the next steps.</p></details><label><input type="checkbox" data-review-confirmed ${sheet.review_confirmed?'checked':''}> I reviewed the source rows and confirm the selected range and excluded data.</label></details>`:''}</fieldset>`}
function renderFiles(){renderWizardProgress();const total=wizard.files.reduce((s,f)=>s+f.size,0);$('#file-selection').innerHTML=`<p>${wizard.files.length} Files Selected · ${(total/1024).toFixed(1)} KiB${wizard.inspecting?' · Inspecting worksheets…':''}</p>${wizard.files.map((f,i)=>`<div class="worksheet-source"><div class="import-actions"><b>${esc(f.webkitRelativePath||f.name)}</b><span>${(f.size/1024).toFixed(1)} KiB</span><button class="btn ghost" data-remove-file="${i}">Remove File</button></div>${(wizard.worksheets[i]||[]).map((sheet,j)=>detectedWorksheetHTML(sheet,i,j)).join('')}<p class="muted">${/\.xlsx$/i.test(f.name)?(wizard.worksheets[i]||[]).filter(x=>x.selected).length+' Worksheets Selected':'CSV — no worksheet selection required'}</p></div>`).join('')}`;
$('#file-selection').querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.removeFile);if(wizard.inspecting){selectFiles(wizard.files.filter((_,j)=>j!==i));return}wizard.files=wizard.files.filter((_,j)=>j!==i);wizard.inspecting=false;const old=wizard.worksheets;wizard.worksheets={};wizard.files.forEach((_,j)=>wizard.worksheets[j]=old[j>=i?j+1:j]);wizard.batch=null;wizard.validation=null;renderFiles()});
$('#file-selection').querySelectorAll('[data-sheet]').forEach(box=>{const sheet=wizard.worksheets[box.dataset.book][box.dataset.sheet];box.querySelector('[data-sheet-selected]').onchange=e=>{sheet.selected=e.target.checked;wizard.batch=null;renderFiles()};const review=box.querySelector('[data-detected-review]');if(review)review.ontoggle=()=>{sheet.review_open=review.open};for(const selector of ['[data-header]','[data-last]']){const input=box.querySelector(selector);if(input)input.onchange=e=>{sheet[selector==='[data-header]'?'header_row':'last_data_row']=e.target.value?Number(e.target.value):null;sheet.review_confirmed=false;box.querySelector('[data-review-confirmed]').checked=false;wizard.batch=null;$('#stage-files').disabled=!filesReady()}}const confirmation=box.querySelector('[data-review-confirmed]');if(confirmation)confirmation.onchange=e=>{sheet.review_confirmed=e.target.checked;wizard.batch=null;$('#stage-files').disabled=!filesReady()}});$('#stage-files').disabled=!filesReady()}
function base64(bytes){let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(text)}
$('#stage-files').onclick=async()=>{if(wizard.batch){renderMappings();showWizardStep(2);return}$('#merchant').disabled=true;const b=$('#stage-files');b.disabled=true;txnMessage('#wizard-message','Extracting and securely staging selected files…');try{await loadImportSettings();const files=await fileDescriptors();wizard.batch=await posAPI('/stage',{files});wizard.mappings={};renderMappings();showWizardStep(2);txnMessage('#wizard-message','Files extracted. Verify each mapping before validation.')}catch(e){txnMessage('#wizard-message',e.message,true);await updateQualityBadge()}finally{b.disabled=false;$('#merchant').disabled=false}};
function renderMappings(){renderProfileMappings()}
function captureMappings(){return captureProfileMappings()}
const findingPages=new Map();
function posHasBlockingIssues(r){const m=r.metrics||{};return r.valid!==true||Boolean(m.invalid_rows||m.ambiguous_duplicates||m.reconciliation_failures)||m.count_reconciled===false||(m.reconciliation||[]).some(source=>source.status==='fail')}
function posActionableFindings(r){const findings=[...(r.findings||[])];for(const source of r.metrics?.reconciliation||[])if(source.status==='fail')for(const issue of source.issues?.length?source.issues:['Source controls do not match the calculated totals.'])findings.push({file_id:source.file_id,filename:source.filename,row:'—',field:'reconciliation',error:issue,correction:'Review the source totals and mapping, then validate again.'});if(r.metrics?.count_reconciled===false)findings.push({filename:'Batch',row:'—',field:'reconciliation',error:'Row accounting did not reconcile.',correction:'Return to Mapping and validate again; do not import this batch.'});return findings}
function validationHTML(r){const m=r.metrics||{},blocked=posHasBlockingIssues(r),notes=[];if(m.duplicate_rows)notes.push(m.duplicate_rows+' duplicate rows excluded.');if((m.reconciliation||[]).some(source=>source.status==='not_available'))notes.push('Independent source controls were not supplied.');return '<div class="import-summary">'+[['Parsed Rows',m.parsed_rows],['Eligible Rows',m.eligible_rows],['Duplicate Exclusions',m.duplicate_rows],['Invalid Rows',m.invalid_rows],['Validation Status',blocked?'Blocked':'Ready for Preview']].map(([k,v])=>'<div><span class="muted">'+k+'</span><strong>'+esc(v??'Unavailable')+'</strong></div>').join('')+'</div><p class="banner '+(blocked?'err':'ok')+'" role="'+(blocked?'alert':'status')+'">'+esc(blocked?'Import is blocked. Review the findings below, correct the source or mapping, and validate again.':'Validation passed. Review transactions before import. '+notes.join(' '))+'</p>'}
function renderFindings(container,findings,key='validation'){let state=findingPages.get(key)||{page:0,size:10,source:''};findingPages.set(key,state);const all=state.source?findings.filter(f=>f.file_id===state.source):findings,pages=Math.max(1,Math.ceil(all.length/state.size));state.page=Math.min(state.page,pages-1);container.innerHTML='<div class="import-actions"><label>Source<select data-source><option value="">All Sources</option>'+[...new Map(findings.map(f=>[f.file_id,f.filename])).entries()].map(([id,name])=>'<option value="'+esc(id)+'" '+(state.source===id?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label><label>Rows per page<select data-size>'+[10,25,50].map(n=>'<option '+(n===state.size?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><div class="table-scroll"><table><thead><tr><th>File / Worksheet</th><th>Source Row</th><th>Field</th><th>Problem / Warning</th><th>Correction</th></tr></thead><tbody>'+all.slice(state.page*state.size,(state.page+1)*state.size).map(f=>'<tr><td>'+esc(f.filename)+'</td><td>'+esc(f.row)+'</td><td>'+esc(titleLabel(f.field))+'</td><td>'+esc(f.error)+'</td><td>'+esc(f.correction)+'</td></tr>').join('')+'</tbody></table></div><div class="import-actions"><button class="btn ghost" data-prev '+(!state.page?'disabled':'')+'>Previous</button><span role="status">Page '+(state.page+1)+' of '+pages+' · '+all.length+' Records</span><button class="btn ghost" data-next '+(state.page+1>=pages?'disabled':'')+'>Next</button></div>';container.querySelector('[data-source]').onchange=e=>{state.source=e.target.value;state.page=0;renderFindings(container,findings,key)};container.querySelector('[data-size]').onchange=e=>{state.size=Number(e.target.value);state.page=0;renderFindings(container,findings,key)};container.querySelector('[data-prev]').onclick=()=>{state.page--;renderFindings(container,findings,key)};container.querySelector('[data-next]').onclick=()=>{state.page++;renderFindings(container,findings,key)}}
function reconciliationHTML(m){return '<h3>Financial Reconciliation</h3><div class="reconciliation-card"><table><tbody><tr><th>Eligible Completed Signed Total</th><td>'+esc(importMoney(m.eligible_total,m.currency))+'</td></tr><tr><th>Eligible Nominal Signed Total</th><td>'+esc(importMoney(m.eligible_nominal_total,m.currency))+'</td></tr></tbody></table><p class="muted">Signed totals include sales, refunds/reversals and negative expenses; this is not sales revenue.</p></div>'+(m.reconciliation||[]).map(c=>'<div class="reconciliation-card"><h4>'+esc(c.filename)+'</h4><table><tbody>'+[['Nominal Net',importMoney(c.nominal_net_total,m.currency)],['Completed Net',importMoney(c.completed_net_total,m.currency)],['Mapped Gross',importMoney(c.mapped_gross_total,m.currency)],['Source Control Status',{pass:'Reconciled',fail:'Control mismatch',not_available:'Unavailable'}[c.status]||c.status],['Parsed Rows',c.parsed_rows]].map(([k,v])=>'<tr><th>'+k+'</th><td>'+esc(v)+'</td></tr>').join('')+'</tbody></table><details><summary>Reconciliation Notes</summary><p>'+esc(c.explanation)+'</p><p>'+esc((c.issues||[]).join('; '))+'</p><p>Source Controls: '+esc(JSON.stringify(c.controls||{}))+'</p></details></div>').join('')}
function importResultHTML(r){const count=r.imported_rows??0,completed=r.ok&&r.status==='committed';return '<p class="banner '+(completed?(count?'ok':'note'):'err')+'">'+esc(completed?(count?'Import completed successfully. '+count+' transactions imported.':'No new transactions imported. '+(r.duplicates_excluded||0)+' duplicates excluded.'):'Import was not completed.')+'</p><table><tbody>'+[['Status',titleLabel(r.status||'Unavailable')],['Files Processed',r.files_processed],['Worksheets Processed',r.worksheets_processed],['Imported Rows',r.imported_rows],['Duplicates Excluded',r.duplicates_excluded],['Rejected Rows',r.rejected_rows],['Imported Total',r.imported_total==null?undefined:importMoney(r.imported_total,r.currency)],['Currency',r.currency],['Completed At',r.completed_at?new Date(r.completed_at).toLocaleString():undefined]].filter(([,v])=>v!==undefined).map(([k,v])=>'<tr><th>'+k+'</th><td>'+esc(v)+'</td></tr>').join('')+'</tbody></table><p class="muted">Imported Total is the backend completed signed total, including negative expenses; not gross sales.</p>'}
$('#validate-pos').onclick=async()=>{const b=$('#validate-pos');$('#merchant').disabled=true;b.disabled=true;try{txnMessage('#wizard-message','Transforming, validating and reconciling all rows…');const r=await posAPI('/'+wizard.batch.batch_id+'/validate',{mappings:captureMappings()});wizard.validation=r;findingPages.delete('validation');$('#validation-results').innerHTML=validationHTML(r)+'<div id="validation-findings"></div>';const findings=posActionableFindings(r);if(findings.length)renderFindings($('#validation-findings'),findings);$('#show-preview').disabled=posHasBlockingIssues(r);$('#wizard-message').textContent='';$('#wizard-message').className='';showWizardStep(3);await updateQualityBadge()}catch(e){txnMessage('#wizard-message',e.message,true)}finally{b.disabled=false;$('#merchant').disabled=false}};
