async function renderPreview(){$('#preview-size').value=String(wizard.previewSize);const r=await api('/api/pos-import/'+wizard.batch.batch_id+'/preview'+q('&offset='+wizard.previewOffset+'&limit='+wizard.previewSize));const blocked=posHasBlockingIssues(r),m=r.metrics||{};$('#preview-summary').innerHTML='<div class="import-summary">'+[['Ready to Import',m.eligible_rows??r.total??'Unavailable'],['Net Transaction Total',importMoney(m.eligible_total,m.currency||M.currency)]].map(([label,value])=>'<div><span class="muted">'+label+'</span><strong>'+esc(value)+'</strong></div>').join('')+'</div><small class="muted">Signed completed net total includes refunds, reversals and expenses; not sales revenue.</small>'+(blocked?'<p class="banner err" role="alert">Import is blocked by validation or reconciliation findings. Return to Validate to review and correct them.</p>':'');$('#preview-validity').textContent=blocked?'Import blocked':'Validated';$('#preview-validity').className='pill '+(blocked?'sev-high':'');$('#wizard-message').textContent='';$('#wizard-message').className='';$('#pos-preview').innerHTML=`<table><thead><tr><th>Reference / ID</th><th>Date (UTC)</th><th>Signed net</th><th>Currency</th><th>Type</th><th>Method</th><th>Status</th><th>Source</th><th>Validation</th></tr></thead><tbody>${(r.rows||[]).map(t=>`<tr><td>${esc(t.external_reference||t.transaction_id)}</td><td>${esc(t.transaction_date)}</td><td>${esc(importMoney(t.amount,t.currency))}</td><td>${esc(t.currency)}</td><td>${esc(t.transaction_type)}</td><td>${esc(t.payment_method)}</td><td>${esc(t.status)}</td><td>${esc(t.source_filename)}${t.source_worksheet?'<br>'+esc(t.source_worksheet):''}</td><td>Eligible</td></tr>`).join('')}</tbody></table>`;$('#preview-page').textContent=`Page ${Math.floor(wizard.previewOffset/wizard.previewSize)+1} of ${Math.max(1,Math.ceil((r.total||0)/wizard.previewSize))} · ${r.total||0} Records`;$('#preview-prev').disabled=!wizard.previewOffset;$('#preview-next').disabled=wizard.previewOffset+wizard.previewSize>=(r.total||0);$('#commit-pos').disabled=blocked||!wizard.validation?.preview_token;}
$('#preview-size').onchange=e=>{wizard.previewSize=Number(e.target.value);wizard.previewOffset=0;renderPreview().catch(e=>txnMessage('#wizard-message',e.message,true))};
