$('#commit-pos').onclick=async()=>{const m=wizard.validation?.metrics||{},replace=m.replaced_rows?'\n\nThis replaces all '+Number(m.replaced_rows).toLocaleString()+' previously imported transactions ('+m.replaced_imports+' earlier import'+(m.replaced_imports===1?'':'s')+') for this business. Manual Single Transaction entries are kept.':'';if(!confirm('Import the validated transactions to this business?'+replace))return;const b=$('#commit-pos');$('#merchant').disabled=true;b.disabled=true;try{const r=await posAPI('/'+wizard.batch.batch_id+'/commit',{preview_token:wizard.validation.preview_token,confirmed:true});if(!r.ok)throw Error(r.error||r.blocking_error||'Import was not committed');$('#import-result').innerHTML=importResultHTML(r);wizard.validation.preview_token=null;showWizardStep(5);await loadLedger();await updateQualityBadge();txnMessage('#wizard-message','Import saved. Review any generated quality alerts.')}catch(e){txnMessage('#wizard-message',e.message,true);try{const r=await api('/api/pos-import/'+wizard.batch.batch_id+q());if(r.state==='committed'){wizard.validation.preview_token=null;$('#import-result').innerHTML=importResultHTML(r.result);showWizardStep(5)}}catch{}await updateQualityBadge()}finally{b.disabled=!wizard.validation?.preview_token;$('#merchant').disabled=false}};
