async function loadTransactionHistory(){await fetchTransactionSettings();await loadLedger()};$('#history-filter').onsubmit=e=>{e.preventDefault();historyOffset=0;loadLedger().catch(e=>txnMessage('#tledger',e.message,true))};$('#history-clear').onclick=()=>{$('#history-filter').reset();historyOffset=0;loadLedger().catch(e=>txnMessage('#tledger',e.message,true))};$('#history-filter').querySelectorAll('input,select').forEach(e=>e.addEventListener('change',()=>{historyOffset=0;$('#history-pagination').querySelectorAll('button,select').forEach(control=>control.disabled=true);const status=$('#history-pagination [role=status]');if(status)status.textContent='Filters changed. Select Filter to apply from page 1.'}));
async function updateQualityBadge(){const badge=$('#quality-badge');badge.hidden=true;if(!M||!mtCan('view_quality_monitoring'))return;const mid=M.id;try{const r=await api('/api/data-quality'+q());if(M?.id!==mid)return;badge.textContent=r.summary.open_alerts;badge.hidden=!r.summary.open_alerts;badge.setAttribute('aria-label',r.summary.open_alerts+' unresolved alerts')}catch{badge.hidden=true}}
const metricGuides={total_import_runs:['Total Import Runs','Number of recorded, retained POS import runs.'],successful_imports:['Successful Imports','Retained POS batches committed, including batches that added zero rows because all were duplicates.'],failed_imports:['Failed Imports','Retained POS batches in Failed, Validation Failed or Integrity Failed state. Expired and cancelled batches are excluded.'],parsed_rows:['Parsed Rows','Rows evaluated using the latest validation of each retained POS run.'],valid_row_rate:['Valid Row Rate','Eligible rows plus exact duplicates, divided by parsed rows, using each retained run’s latest validation.'],invalid_row_rate:['Invalid Row Rate','Invalid rows divided by parsed rows, using each retained run’s latest validation.'],duplicate_rate:['Duplicate Rate','Exact duplicate exclusions divided by parsed rows, using each retained run’s latest validation.'],reconciliation_failures:['Reconciliation Failures','Source reconciliation failures summed across each retained POS run’s latest validation.'],open_alerts:['Unresolved Alerts','Quality alerts that are Open or Acknowledged; resolved alerts are excluded.'],last_successful_import:['Last Successful Import','Completion time returned for the most recently created retained committed POS run, including zero-row batches.']};
