let qualityTab='overview',qualityDetailRequest=0,qualitySelectedRun=null,qualityAlertPage=0,qualityAlertSize=10,qualityLoadingMerchant=null;
const qualityRuleDescriptions={
required_fields:['Required Fields','Checks required transaction values and mapping completeness.','Prevents incomplete financial records.'],
uniqueness:['Uniqueness','Checks external references and transaction fingerprints against source and saved records.','Prevents duplicate financial entries; ambiguous matches block import.'],
monetary_precision:['Monetary Precision','Checks finite decimal amounts, existing limits and two-decimal precision.','Prevents invalid amounts and unsupported precision.'],
date_validity:['Date Validity','Checks supported dates, parsing configuration and future-date restrictions.','Places transactions in a valid reporting period.'],
currency_validity:['Currency Validity','Checks transaction currencies against the selected merchant’s base currency.','Prevents unsupported currency mixing; no FX conversion is performed.'],
status_validity:['Status Validity','Checks supported transaction types and statuses.','Keeps completed, pending, failed and voided records distinct.'],
payment_method_validity:['Payment Method Validity','Checks existing canonical methods and explicit source translations.','Protects payment analytics without guessing missing methods.'],
count_reconciliation:['Count Reconciliation','Checks parsed, eligible, duplicate and invalid row accounting.','Makes exclusions and invalid records visible.'],
financial_reconciliation:['Financial Reconciliation','Compares calculated totals with independently supplied source controls when available.','Exposes mismatches without inventing source totals.'],
merchant_authorization:['Merchant Authorization','Checks current account role, merchant membership and delegated permissions.','Protects merchant isolation.'],
import_integrity:['Import Integrity','Checks signed staged data, preview integrity and durable journal consistency at applicable stages.','Protects imports from tampering and inconsistent commits.']};
const qualityNames={session_expired:'Import Session Expired',not_available:'Unavailable',not_validated:'Not Validated',informational:'Informational',open:'Open',acknowledged:'Acknowledged',resolved:'Resolved'};
const qualityLabel=v=>qualityNames[v]||displayValue(v);
const availableCount=v=>v==null?'Unavailable':countText(v);
function selectQualityTab(name,focus=false){if(!['overview','history','alerts'].includes(name))return;qualityTab=name;document.querySelectorAll('[data-quality-tab]').forEach(b=>{const active=b.dataset.qualityTab===name;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus){b.focus();b.scrollIntoView({block:'nearest',inline:'nearest'})}});document.querySelectorAll('[data-quality-panel]').forEach(p=>p.hidden=p.dataset.qualityPanel!==name)}
document.querySelectorAll('[data-quality-tab]').forEach((b,i)=>{b.onclick=()=>selectQualityTab(b.dataset.qualityTab);b.onkeydown=e=>{const tabs=[...document.querySelectorAll('[data-quality-tab]')];let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectQualityTab(tabs[next].dataset.qualityTab,true)}}});
function qualitySources(run){const files=run.files||run.metrics?.files||[];return [...new Set(files.map(f=>f.filename).filter(Boolean))]}
function qualitySheets(run){return [...new Set((run.files||run.metrics?.files||[]).map(f=>f.worksheet).filter(Boolean))]}
function renderRunHistory(){const runs=qualitySnapshot?.runs||[],pages=Math.max(1,Math.ceil((qualitySnapshot?.run_total||0)/runSize));runPage=Math.min(runPage,pages-1);$('#quality-runs').innerHTML=runs.length?'<table><thead><tr><th>Created At</th><th>Source File</th><th>Worksheets</th><th>Import Status</th><th>Imported Rows</th><th>Duplicates</th><th>Issues</th><th>Actions</th></tr></thead><tbody>'+runs.map(run=>{const measured=run.validation_version>0,files=qualitySources(run),sheets=qualitySheets(run);return '<tr><td>'+esc(localTime(run.created_at))+'</td><td>'+esc(files.join(', ')||'Source unavailable')+'</td><td>'+esc(sheets.join(', ')||'Not provided (may be CSV)')+'</td><td>'+statusBadge(run.state)+'</td><td>'+availableCount(run.state==='committed'?run.result?.imported_rows:null)+'</td><td>'+availableCount(measured?run.metrics?.duplicate_rows:null)+'</td><td>'+availableCount(measured?run.metrics?.invalid_rows:null)+'</td><td><button class="btn ghost" data-run="'+esc(run.batch_id)+'" aria-label="View import summary for '+esc(files.join(', ')||'import')+'">View Summary</button></td></tr>'}).join('')+'</tbody></table>':'<p class="muted" role="status">No import runs match this status.</p>';tablePager($('#run-pagination'),{page:runPage,size:runSize,total:qualitySnapshot?.run_total||0,label:'Matching Runs'},(page,size)=>{runPage=page;runSize=size;loadDataQuality().catch(()=>{})});$('#run-cap-note').textContent='Overview metrics use all retained POS runs; table filters apply across matching history.';bindQualityRunButtons($('#quality-runs'))}
function bindQualityRunButtons(root){root.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>showRun(b.dataset.run).catch(e=>txnMessage('#quality-message',e.message,true)))}
function renderQualityRules(rules){const evidence=qualitySelectedRun?.validation_version>0?qualitySelectedRun.metrics?.rules:null;$('#quality-rules').innerHTML='<p class="muted">'+(evidence?'Recorded results for the explicitly selected import ('+esc(qualitySources(qualitySelectedRun).join(', ')||'source unavailable')+'). These are not global results.':'No import selected. Open an Import Summary to inspect actual run-specific evidence. Rules do not all run at every lifecycle stage.')+'</p><div class="quality-rule-grid">'+rules.map(key=>{const d=qualityRuleDescriptions[key]||[qualityLabel(key),'Built-in application check.','Protects transaction integrity.'];return '<article class="quality-rule"><h3>'+esc(d[0])+'</h3><p><strong>What is checked:</strong> '+esc(d[1])+'</p><p><strong>Why it matters:</strong> '+esc(d[2])+'</p><p class="muted">Recorded result: '+(evidence&&Object.hasOwn(evidence,key)?statusBadge(evidence[key]):'Not available for a selected run')+'</p></article>'}).join('')+'</div>'}
function bindQualityAlertActions(root){bindQualityRunButtons(root);root.querySelectorAll('[data-alert]').forEach(button=>button.onclick=async()=>{const mid=M.id,reason=prompt('Provide reason/evidence (8–500 characters). Alert status never bypasses validation.');if(reason===null)return;button.disabled=true;try{await api('/api/data-quality/alerts/'+button.dataset.alert,{method:'POST',body:JSON.stringify({merchant:mid,state:button.dataset.state,reason})});if(M?.id===mid){const dialog=root.closest('dialog');if(dialog){dialog.close();dialog.remove()}qualityAlertPage=0;await loadDataQuality();await updateQualityBadge()}}catch(error){if(M?.id===mid)txnMessage('#quality-message',error.message,true)}finally{button.disabled=false}})}
function qualityAlertActions(a){return (a.batch_id?'<button class="btn ghost sm" data-run="'+esc(a.batch_id)+'">View Related Import</button>':'')+(a.state==='open'&&mtCan('acknowledge_quality_alerts')?'<button class="btn sm" data-alert="'+esc(a.alert_id)+'" data-state="acknowledged">Acknowledge</button>':'')+(a.state==='acknowledged'&&mtCan('resolve_quality_alerts')?'<button class="btn sm" data-alert="'+esc(a.alert_id)+'" data-state="resolved">Resolve with Evidence</button>':'')}
function renderQualityAlerts(alerts){const box=$('#quality-alerts');box.innerHTML=alerts.length?'<table class="table table-sm"><thead><tr><th>Alert</th><th>Severity</th><th>Status</th><th>Detected</th><th>Actions</th></tr></thead><tbody>'+alerts.map(a=>'<tr><td>'+esc(qualityLabel(a.rule))+'</td><td>'+statusBadge(a.severity)+'</td><td>'+statusBadge(a.state)+'</td><td>'+esc(a.detected_at?localTime(new Date(a.detected_at*1000).toISOString()):'Unavailable')+'</td><td><button class="btn ghost sm" data-quality-detail="'+esc(a.alert_id)+'">View Details</button></td></tr>').join('')+'</tbody></table>':'<p class="muted">No matching alerts.</p>';box.querySelectorAll('[data-quality-detail]').forEach(button=>button.onclick=()=>{const a=alerts.find(a=>a.alert_id===button.dataset.qualityDetail);if(!a)return;const {dialog}=financingDialog(qualityLabel(a.rule),qualityKeyValues([['Description',a.description],['Affected Rows',a.affected_rows],['Recommended Action',a.recommendation],['Related Import',a.batch_id]])+'<div class="import-actions">'+qualityAlertActions(a)+'</div>');bindQualityAlertActions(dialog)});tablePager($('#alert-pagination'),{page:qualityAlertPage,size:qualityAlertSize,total:qualitySnapshot?.alert_total||0,label:'Matching Alerts'},(page,size)=>{qualityAlertPage=page;qualityAlertSize=size;loadDataQuality().catch(()=>{})})}
function renderQualityAttention(alerts){$('#quality-attention').innerHTML=alerts.length?'<ul>'+alerts.slice(0,5).map(a=>'<li><b>'+esc(qualityLabel(a.rule))+'</b> · '+esc(qualityLabel(a.severity))+' — '+esc(a.description)+'</li>').join('')+'</ul>':'<p class="muted">No unresolved alerts for this business.</p>'}
async function loadDataQuality(){const mid=M.id,button=$('#quality-refresh');if(button.disabled&&qualityLoadingMerchant===mid)return;const request=++qualityRequest;qualityLoadingMerchant=mid;if(qualitySnapshot?.merchant_id!==mid){qualitySnapshot=null;qualitySelectedRun=null;$('#quality-runs').replaceChildren();$('#quality-alerts').replaceChildren();$('#quality-rules')?.replaceChildren()}button.disabled=true;$('#quality-view-all').disabled=true;for(const id of ['run-pagination','alert-pagination'])$('#'+id).querySelectorAll('button,select').forEach(e=>e.disabled=true);$('#alerts-filter').querySelectorAll('input,select,button').forEach(e=>e.disabled=true);$('#run-state').disabled=true;button.setAttribute('aria-busy','true');$('#quality-kpis').setAttribute('aria-busy','true');$('#quality-message').className='muted';$('#quality-message').textContent='Refreshing recorded monitoring data…';try{const filters=new URLSearchParams({merchant:mid,severity:$('#alert-severity').value,state:$('#alert-state').value,start:$('#alert-start').value,end:$('#alert-end').value,run_state:$('#run-state').value,run_offset:runPage*runSize,run_limit:runSize,alert_offset:qualityAlertPage*qualityAlertSize,alert_limit:qualityAlertSize});const r=await api('/api/data-quality?'+filters);if(request!==qualityRequest||M?.id!==mid)return;qualitySnapshot={...r,merchant_id:mid};runPage=Math.floor((r.run_offset||0)/runSize);qualityAlertPage=Math.floor((r.alert_offset||0)/qualityAlertSize);$('#quality-kpis').className='quality-metrics';$('#quality-kpis').innerHTML=Object.entries(r.summary).filter(([k])=>['total_import_runs','successful_imports','failed_imports','parsed_rows','valid_row_rate','invalid_row_rate','open_alerts'].includes(k)).map(([k,v])=>{const [label,help]=metricGuides[k]||[titleLabel(k),'Metric returned by the existing backend.'],rate=k.endsWith('_rate'),value=rate?(v==null?'N/A':(v*100).toFixed(1)+'%'):k==='last_successful_import'?(v?localTime(v):'Not available'):countText(v);return '<div class="card" data-metric="'+esc(k)+'"><div class="metric-heading"><span class="muted">'+esc(label)+'</span><details class="metric-help"><summary aria-label="About '+esc(label)+'" title="'+esc(help)+'">i</summary><p>'+esc(help)+'</p></details></div><div class="kpi">'+esc(value)+'</div>'+(rate&&v==null?'<p class="metric-empty">No parsed rows available for this rate.</p>':'')+'</div>'}).join('');$('#quality-formula').textContent=r.summary.formula;$('#quality-metric-definitions').innerHTML=Object.values(metricGuides).map(([label,help])=>'<dt>'+esc(label)+'</dt><dd>'+esc(help)+'</dd>').join('');renderRunHistory();renderQualityAlerts(r.alerts||[]);renderQualityAttention(r.attention||[]);if($('#quality-rules'))renderQualityRules(r.rules||[]);selectQualityTab(qualityTab);$('#quality-message').className='muted';$('#quality-message').textContent='Snapshot retrieved '+localTime(r.evaluated_at)+'. Checks run only through existing foreground requests.';await updateQualityBadge()}catch(e){if(request===qualityRequest&&M?.id===mid)txnMessage('#quality-message','Refresh failed: '+e.message+'. Previously retrieved data, if shown, may be stale.',true);throw e}finally{if(request===qualityRequest){button.disabled=false;$('#quality-view-all').disabled=false;for(const id of ['run-pagination','alert-pagination'])$('#'+id).querySelectorAll('button,select').forEach(e=>e.disabled=false);$('#alerts-filter').querySelectorAll('input,select,button').forEach(e=>e.disabled=false);$('#run-state').disabled=false;button.setAttribute('aria-busy','false');$('#quality-kpis').setAttribute('aria-busy','false');if(qualitySnapshot?.merchant_id===M?.id){renderRunHistory();renderQualityAlerts(qualitySnapshot.alerts||[])}}}}
function qualityKeyValues(values){return '<dl class="quality-facts">'+values.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v==null?'Unavailable':String(v))+'</dd></div>').join('')+'</dl>'}
function qualityReconciliation(m,measured){if(!measured||!m.reconciliation?.length)return '<p class="muted">Reconciliation has not produced recorded results for this run.</p>';return m.reconciliation.map(c=>{const controls=c.controls||{},netKey=controls.basis==='nominal_net'?'nominal_net_total':'completed_net_total';return '<article class="reconciliation-card"><h4>'+esc(c.filename||'Source unavailable')+'</h4><p>Source control status: '+esc({pass:'Reconciled',fail:'Control mismatch',not_available:'Unavailable'}[c.status]||qualityLabel(c.status))+'</p><div class="table-scroll"><table><thead><tr><th>Measure</th><th>Source-reported</th><th>Calculated</th><th>Difference</th></tr></thead><tbody>'+[['Transaction rows',controls.count,c.parsed_rows],['Net total ('+(controls.basis||'completed_net')+')',controls.net_total,c[netKey]],['Mapped gross total',controls.gross_total,c.mapped_gross_total]].map(([k,reported,calculated])=>'<tr><th>'+esc(k)+'</th><td>'+esc(reported==null||reported===''?'Unavailable':reported)+'</td><td>'+esc(calculated==null?'Unavailable':calculated)+'</td><td>Not supplied by backend</td></tr>').join('')+'</tbody></table></div><p>'+esc(c.explanation||'No explanation supplied')+'</p><p>'+esc((c.issues||[]).join('; '))+'</p><p class="muted">Currency: '+esc(m.currency||'Unavailable')+'. No independent controls are inferred from calculated totals. Numeric differences are not returned by this API.</p></article>'}).join('')}
async function showRun(bid){const mid=M.id,request=++qualityDetailRequest,r=await api('/api/data-quality/runs/'+encodeURIComponent(bid)+q());if(M?.id!==mid||request!==qualityDetailRequest)return;qualitySelectedRun=r;const m=r.metrics||{},measured=r.validation_version>0,committed=r.state==='committed',files=qualitySources(r),sheets=qualitySheets(r),currencies=[...new Set((r.files||[]).flatMap(f=>f.currency_hints||[]))];const explanations={staged:'Files have been uploaded and parsed. Validation has not yet completed. No transactions have been committed.',validated:'Validation completed. Review eligible, duplicate and invalid transactions. No transactions have been committed.',committed:'Import completed. The imported and excluded counts below come from the recorded commit result.',validation_failed:'Validation failed. No transactions were committed by this batch. Review the findings and source controls.',failed:'Import failed. Review the recorded reason and recommended action.',expired:'The import session expired. Review the recorded commit state before starting a new import.',cancelled:'The import was cancelled. Review the recorded lifecycle and results.',integrity_failed:'An integrity check blocked this import. Review the recorded findings; do not bypass validation.',committing:'The commit is being recovered or finalized. Completion is not yet confirmed.'};$('#run-detail').innerHTML='<p class="banner note">'+esc(explanations[r.state]||'Review the recorded lifecycle; completion is not inferred.')+'</p><h3>Import Information</h3>'+qualityKeyValues([['Source filename',files.join(', ')||null],['Worksheet names',sheets.join(', ')||null],['Created',localTime(r.created_at)],['Import status',qualityLabel(r.state)],['Detected / recorded currency',currencies.join(', ')||m.currency||r.result?.currency||null],['Initiated by',r.actor_label||null]])+'<h3>Transaction Results</h3>'+qualityKeyValues([['Parsed rows',m.parsed_rows],['Eligible rows',measured?m.eligible_rows:null],['Imported rows',committed?r.result?.imported_rows:null],['Duplicate rows',measured?m.duplicate_rows:null],['Invalid rows',measured?m.invalid_rows:null],['Excluded rows (exact duplicates)',committed?r.result?.duplicates_excluded:null],['Reconciliation status',measured?(m.reconciliation_failures>0?'Control mismatch':m.reconciliation?.some(c=>c.status==='not_available')?'Source controls unavailable':m.reconciliation?.length?'See recorded source results':'Unavailable'):null]])+'<h3>Validation Findings</h3><div id="run-findings"></div><h3>Reconciliation</h3>'+qualityReconciliation(m,measured);if(r.findings?.length)renderFindings($('#run-findings'),r.findings,'run-'+bid);else $('#run-findings').innerHTML='<p class="muted">'+(measured?'No recorded validation findings.':'Validation findings are not yet available.')+'</p>';$('#quality-rules')&&renderQualityRules(qualitySnapshot?.rules||[]);if(!$('#run-dialog').open)$('#run-dialog').showModal();$('#run-summary-title').focus({preventScroll:true});$('#run-detail').scrollTop=0}
$('#close-run').onclick=()=>$('#run-dialog').close();$('#quality-view-all').onclick=()=>{for(const id of ['alert-severity','alert-state','alert-start','alert-end'])$('#'+id).value='';qualityAlertPage=0;selectQualityTab('alerts',true);loadDataQuality().catch(()=>{})};$('#quality-refresh').onclick=()=>loadDataQuality().catch(()=>{});$('#alerts-filter').onsubmit=e=>{e.preventDefault();qualityAlertPage=0;loadDataQuality().catch(()=>{})};$('#run-state').onchange=()=>{runPage=0;loadDataQuality().catch(()=>{})};
for(const id of ['alert-severity','alert-state'])$('#'+id).querySelectorAll('option').forEach(o=>{if(o.value){const raw=o.value;o.value=raw;o.textContent=qualityLabel(raw)}});
selectQualityTab('overview');
